def copy_bank_details(apps, schema_editor):
    """Fund.bank_details JSON rows → FundBankAccount table rows (DECISIONS.md D18)."""
    Fund = apps.get_model("content", "Fund")
    FundBankAccount = apps.get_model("content", "FundBankAccount")
    for fund in Fund.objects.exclude(bank_details=[]):
        for order, row in enumerate(fund.bank_details or []):
            FundBankAccount.objects.create(
                fund=fund,
                sort_order=order,
                **{key: str(row.get(key) or "") for key in
                   ("bank", "account_name", "branch", "number", "routing", "swift")},
            )


